fn tr(uk: bool, a: &'static str, b: &'static str) -> &'static str { if uk { a } else { b } }
impl Editor {
    fn record(&mut self, old: Project) { if old != self.project { self.undo.push(old); if self.undo.len()>100 { self.undo.remove(0); } self.redo.clear(); } }
    fn undo(&mut self) { if let Some(p)=self.undo.pop(){self.redo.push(std::mem::replace(&mut self.project,p));} }
    fn redo(&mut self) { if let Some(p)=self.redo.pop(){self.undo.push(std::mem::replace(&mut self.project,p));} }
    fn save(&mut self, as_new: bool) {
        let path = if as_new || self.path.is_none() { rfd::FileDialog::new().set_file_name("project.forge.json").save_file() } else { self.path.clone() };
        if let Some(path)=path {
            // Save As copies referenced assets to preserve relative paths.
            let result = (|| -> Result<(),String> {
                if let Some(old)=&self.path { for o in &self.project.objects { for s in o.sprite.iter().chain(o.production.particle_texture.iter()).chain(o.production.normal_map.iter()).chain(o.pro.sound.iter().map(|a|&a.path)) { if s.is_empty(){continue;} if !forge_engine::valid_asset(s){return Err("Invalid asset path".into());} let from=old.parent().unwrap().join(s); let to=path.parent().unwrap().join(s); if from!=to { std::fs::create_dir_all(to.parent().unwrap()).map_err(|e|e.to_string())?; std::fs::copy(from,to).map_err(|e|e.to_string())?; } } } }
                self.project.save(&path)
            })();
            match result { Ok(())=>{ self.path=Some(path); self.saved=self.project.clone(); self.status="Saved".into(); }, Err(e)=>self.status=e }
        }
    }
    fn confirm_discard(&self) -> bool { self.saved==self.project || matches!(rfd::MessageDialog::new().set_title("Forge Engine").set_description("Discard unsaved changes? / Відкинути незбережені зміни?").set_buttons(rfd::MessageButtons::YesNo).show(),rfd::MessageDialogResult::Yes) }
    fn open(&mut self) { if !self.confirm_discard(){return;} if let Some(path)=rfd::FileDialog::new().add_filter("Forge JSON", &["json"]).pick_file(){ match Project::load(&path){ Ok(p)=>{self.project=p.clone(); self.saved=p; self.path=Some(path); self.selected=None; self.pro.multi.clear(); self.pro.last_scan=None; self.undo.clear(); self.redo.clear(); self.textures.clear(); self.stamps.clear(); self.preview=0.; self.preview_play=false; self.status="Opened".into();},Err(e)=>self.status=e } } }
    fn import(&mut self){ if self.path.is_none(){self.save(false);} let Some(src)=rfd::FileDialog::new().add_filter("Image", &["png","jpg","jpeg"]).pick_file() else{return;}; self.import_path(src); }
    fn import_path(&mut self,src:PathBuf){if self.path.is_none(){self.save(false);} let Some(root)=self.path.as_ref().and_then(|p|p.parent()).map(|p|p.to_path_buf()) else{return;}; let result=(||->Result<Object,String>{ let img=image::open(&src).map_err(|e|e.to_string())?; let ext=src.extension().and_then(|x|x.to_str()).unwrap_or("png"); let rel=format!("assets/{}.{}",Uuid::new_v4(),ext); std::fs::create_dir_all(root.join("assets")).map_err(|e|e.to_string())?; std::fs::copy(&src,root.join(&rel)).map_err(|e|e.to_string())?; let mut o=Object::new(src.file_stem().and_then(|x|x.to_str()).unwrap_or("Sprite"),[0.,0.],[img.width() as f32,img.height() as f32],[255;4]); o.sprite=Some(rel); Ok(o)})(); match result {Ok(o)=>{self.selected=Some(o.id);self.project.objects.push(o);},Err(e)=>self.status=e} }
}
fn editor_qa(path:&std::path::Path)->Result<(),String>{
 let p=Project::load(path)?;let mut e=Editor::default();e.project=p.clone();e.saved=p.clone();e.path=Some(path.to_owned());
 let id=p.objects.iter().find(|o|o.player).ok_or("No player")?.id;
 let old=e.project.clone();e.project.objects.iter_mut().find(|o|o.id==id).unwrap().position[0]+=32.;e.record(old);e.undo();if e.project!=p{return Err("Undo mismatch".into());}e.redo();if e.project==p{return Err("Redo mismatch".into());}e.undo();
 let mut copy=p.clone();let new=forge_engine::instantiate(forge_engine::prefab(&copy,id));if new.is_empty()||new.iter().any(|o|copy.objects.iter().any(|old|old.id==o.id)){return Err("Prefab identity".into());}copy.objects.extend(new);let child=copy.objects.last().unwrap().id;forge_engine::reparent(&mut copy,child,Some(id))?;if forge_engine::reparent(&mut copy,id,Some(child)).is_ok(){return Err("Hierarchy cycle accepted".into());}
 let tile=forge_engine::paint_tile(&mut copy,[99,99],32,8,None,true);if !copy.objects.iter().any(|o|o.id==tile){return Err("Paint failed".into());}forge_engine::erase_tile(&mut copy,[99,99],32,8);if copy.objects.iter().any(|o|o.id==tile){return Err("Erase failed".into());}
 let player=p.objects.iter().find(|o|o.id==id).unwrap();for clip in player.clips.values(){for t in [0.,0.1,1.,10.]{let uv=clip.uv(t);if uv.iter().flatten().any(|v|!v.is_finite()||*v<0.||*v>1.00001){return Err("Animation UV invalid".into());}}}
 let file=std::env::temp_dir().join(format!("forge-qa-{}.json",Uuid::new_v4()));let result=(|| -> Result<(),String> {copy.save(&file)?;if Project::load(&file)?!=copy{return Err("Scene roundtrip mismatch".into());}Ok(())})();let _=std::fs::remove_file(file);result?;
 e.play=Some(e.project.clone());let mut sim=Simulation::default();sim.step(e.play.as_mut().unwrap(),1./60.,[1.,0.]);e.play=None;if e.project!=p{return Err("Play modified source scene".into());}
 Ok(())
}
fn main(){ if std::env::args().nth(1).as_deref()==Some("--editor-qa"){let path=std::env::args_os().nth(2).map(PathBuf::from).unwrap_or_else(||PathBuf::from("examples/signal_lost/project.forge.json"));match editor_qa(&path){Ok(())=>{println!("EDITOR MODEL QA PASS");return;},Err(e)=>{eprintln!("EDITOR MODEL QA FAIL: {e}");std::process::exit(1);}}} App::new().add_plugins(DefaultPlugins.set(ImagePlugin::default_nearest()).set(WindowPlugin{primary_window:Some(Window{title:"Forge Engine 0.7.4 — Native Editor".into(),resolution:(1360.,850.).into(),..default()}),..default()})).add_plugins(EguiPlugin::default()).init_resource::<Editor>().add_systems(Startup,setup).add_systems(EguiPrimaryContextPass,editor_ui).add_systems(PostUpdate,(sync_viewport,sync_game_camera,viewport::preview_particles).before(bevy::transform::TransformSystem::TransformPropagate)).run(); }
fn setup(mut commands:Commands, mut settings:ResMut<EguiGlobalSettings>, mut images:ResMut<Assets<Image>>){settings.auto_create_primary_context=false; commands.spawn((Camera2d,PrimaryEguiContext,bevy::render::view::RenderLayers::layer(1))); let mut image=Image::new_fill(Extent3d{width:640,height:480,depth_or_array_layers:1},TextureDimension::D2,&[22,26,32,255],TextureFormat::Bgra8UnormSrgb,RenderAssetUsages::default()); image.texture_descriptor.usage=TextureUsages::TEXTURE_BINDING|TextureUsages::COPY_DST|TextureUsages::RENDER_ATTACHMENT; let target=images.add(image); commands.spawn((Camera2d,Camera{order:-1,target:RenderTarget::Image(target.clone().into()),clear_color:ClearColorConfig::Custom(Color::srgb_u8(22,26,32)),..default()},SceneCamera)); commands.insert_resource(ViewTarget(target)); let mut preview=Image::new_fill(Extent3d{width:640,height:360,depth_or_array_layers:1},TextureDimension::D2,&[22,26,32,255],TextureFormat::Bgra8UnormSrgb,RenderAssetUsages::default()); preview.texture_descriptor.usage=TextureUsages::TEXTURE_BINDING|TextureUsages::COPY_DST|TextureUsages::RENDER_ATTACHMENT;let handle=images.add(preview);commands.spawn((Camera2d,Camera{order:-2,target:RenderTarget::Image(handle.clone().into()),is_active:false,..default()},GamePreviewCamera));commands.insert_resource(GamePreviewTarget(handle));}
